import{_ as a,o as r,c as s,a as e,b as o}from"./chunks/framework.DzJZdBQK.js";const f=JSON.parse('{"title":"写作课作业-028","description":"","frontmatter":{"date":"2020-08-16T21:29:34","title":"写作课作业-028","categories":["写作","作业"],"tags":["写作","作业"]},"headers":[],"relativePath":"posts/homework/028.md","filePath":"posts/homework/028.md"}'),n={name:"posts/homework/028.md"};function l(p,t,c,i,d,m){return r(),s("div",null,[...t[0]||(t[0]=[e("blockquote",null,[e("p",null,"我们工作和生活有很多“舒适圈”，你是怎么样不断地突破自己舒适圈，获得成长的？至少用一个类比。")],-1),e("p",null,[o("舒适区（Comfort Zone）或舒适圈，指的是一个人所处的一种环境的状态，和习惯的行动，人会在这种安乐窝的状态中感到舒适并且缺乏危机感。非常成功的人通常会走出自己的舒适区，去达成自己的目标。舒适区是一种"),e("a",{href:"https://zh.wikipedia.org/wiki/%E7%B2%BE%E7%A5%9E",target:"_blank",rel:"noreferrer"},"精神"),o("状态，它导致人们进入并且维持一种不现实精神行为之中，这种情况会给人带来一种非理性的安全感。类似惰性，当人围绕自己生活的某一部分建立了一个舒适区之后，他就会开始倾向于待在舒适区内，而不是走出舒适区。走出一个人的舒适区，他们必须在新的环境中找到新的不同的行动方式，同时回应这些新的行动方式所导致的后果。")],-1),e("p",null,"心理学研究说，人类对于外部世界的认识可分为三个区域：舒适区（comfort zone），学习区（stretch zone），和恐慌区（stress zone）。",-1),e("p",null,"我的第一份工作干了7，8年，换了工作后，我时常会想为什么不早点出来呢？业内有个段子时这么说的，“10年工作经验，不，是一年的工作经验工作了10年。”，感觉自己就是个典型。因为换工作学了Java，感觉自己像是打开了新世界的大门，各种技术，各种架构一股脑的涌进来。虽然学习各种新技术很痛苦，但可以玩新技术，自己是兴奋的，就这样痛并快乐着。之前的工作学了新东西，但为了保障老客户的使用，也不敢轻易使用，越时不用，越不敢用，久而久之，连学习的动力都没那么强了。也因为这样，自己挺担心离职了找不到工作， 所幸那时读了笑来老师的《把时间当朋友》果断离职了，再后来换工作，创业，心态上就好很多了，正所谓“树挪死，人挪活”。",-1),e("p",null,"自己Javascript没学好，后来碰到前端问题自己不敢动手，能找人就找人做，自己躲在舒适圈里。",-1),e("p",null,"前一段时间，接了个PHP的项目。语言和框架框架的文档很快就看完了。但开发的时候，写着写着就会想，这个要是用Java就好了，分分钟给你搞出来，特别是当时碰到了个多线程的问题，自己没少抱怨。今天来看其实是舒适区在作怪。后面解决这个问题是多看了几遍框架的文档和同事一起解决的。后续的功能开发也算顺利。",-1),e("p",null,"人的知识就好比一个圆圈，圆圈里面是已知的，圆圈外面是未知的。你知道得越多，圆圈也就越大，你不知道的也就越多。刘未鹏在《暗时间》中说“困难的路越走越容易，容易的路越走越难”。",-1)])])}const _=a(n,[["render",l]]);export{f as __pageData,_ as default};
